-- ============ ESQUEMA ============

CREATE TABLE IF NOT EXISTS "_schema" (
    "id" INTEGER NOT NULL,
    "version" INTEGER NOT NULL,
    "aplicada_en" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "asignaciones_solicitudes" (
    "id" SERIAL,
    "solicitud_id" INTEGER NOT NULL,
    "equipo_id" INTEGER NOT NULL,
    "usuario_id" INTEGER,
    "asignado_por" INTEGER NOT NULL,
    "desde_campaña_id" INTEGER,
    "tipo_asignacion" VARCHAR(20) DEFAULT 'manual'::character varying,
    "fecha_asignacion" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    "fecha_desasignacion" TIMESTAMP,
    "motivo_desasignacion" TEXT,
    PRIMARY KEY ("id"),
    UNIQUE ("solicitud_id", "fecha_desasignacion")
);

CREATE TABLE IF NOT EXISTS "audit_log" (
    "id" SERIAL,
    "usuario_id" INTEGER NOT NULL,
    "accion" TEXT NOT NULL,
    "target_type" TEXT,
    "target_id" INTEGER,
    "detalle" JSONB,
    "ip_address" TEXT,
    "user_agent" TEXT,
    "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "campañas_equipo" (
    "id" SERIAL,
    "campaña_id" INTEGER NOT NULL,
    "equipo_id" INTEGER NOT NULL,
    "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("id"),
    UNIQUE ("campaña_id")
);

CREATE TABLE IF NOT EXISTS "config_bonos" (
    "id" SERIAL,
    "usuario_id" INTEGER,
    "mes" TEXT,
    "bono1" REAL DEFAULT 3000,
    "bono2" REAL DEFAULT 7000,
    "bono3" REAL DEFAULT 12000,
    "bono4" REAL DEFAULT 20000,
    "bono5" REAL DEFAULT 30000,
    "bono6" REAL DEFAULT 40000,
    "meta_equipo" REAL DEFAULT 40000,
    "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("id"),
    UNIQUE ("mes")
);

CREATE TABLE IF NOT EXISTS "equipo_usuarios" (
    "id" SERIAL,
    "equipo_id" INTEGER NOT NULL,
    "usuario_id" INTEGER NOT NULL,
    "es_lider" INTEGER DEFAULT 0 NOT NULL,
    "fecha_ingreso" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    "fecha_salida" TIMESTAMP,
    "motivo_salida" TEXT,
    PRIMARY KEY ("id"),
    UNIQUE ("usuario_id", "fecha_salida")
);

CREATE TABLE IF NOT EXISTS "equipos" (
    "id" SERIAL,
    "nombre" VARCHAR(100) NOT NULL,
    "descripcion" TEXT,
    "activo" INTEGER DEFAULT 1 NOT NULL,
    "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("id"),
    UNIQUE ("nombre")
);

CREATE TABLE IF NOT EXISTS "gestines" (
    "id" SERIAL,
    "solicitud_id" INTEGER NOT NULL,
    "usuario_id" INTEGER NOT NULL,
    "tipo_gestion" TEXT NOT NULL,
    "observacion" TEXT,
    "fecha_gestion" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "gestiones" (
    "id" SERIAL,
    "solicitud_id" INTEGER NOT NULL,
    "usuario_id" INTEGER NOT NULL,
    "tipo_gestion" TEXT NOT NULL,
    "observacion" TEXT,
    "fecha_gestion" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    "gestion_maestro_id" INTEGER,
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "gestiones_maestro" (
    "id" SERIAL,
    "nombre" TEXT NOT NULL,
    "descripcion" TEXT,
    "usuario_id" INTEGER NOT NULL,
    "estado" TEXT DEFAULT 'activa'::text,
    "total_solicitudes" INTEGER DEFAULT 0,
    "gestionadas" INTEGER DEFAULT 0,
    "fecha_limite" DATE,
    "fecha_inicio" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    "fecha_fin" TIMESTAMP,
    "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    "solicitudes_ids" TEXT,
    "equipo_id" INTEGER,
    "asignado_a" INTEGER,
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "gestiones_maestro_solicitudes" (
    "id" SERIAL,
    "gestion_maestro_id" INTEGER NOT NULL,
    "id_solicitud" INTEGER NOT NULL,
    "semaforo" TEXT DEFAULT 'sin_clasificar'::text NOT NULL,
    "updated_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    "updated_by" INTEGER,
    PRIMARY KEY ("id"),
    UNIQUE ("gestion_maestro_id", "id_solicitud")
);

CREATE TABLE IF NOT EXISTS "gestiones_relaciones" (
    "id" SERIAL,
    "relacion_id" INTEGER NOT NULL,
    "usuario_id" INTEGER NOT NULL,
    "tipo_gestion" TEXT NOT NULL,
    "observacion" TEXT,
    "fecha_gestion" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "historial_actualizaciones" (
    "id" SERIAL,
    "solicitud_id" INTEGER NOT NULL,
    "usuario_id" INTEGER NOT NULL,
    "campo" TEXT NOT NULL,
    "valor_anterior" TEXT,
    "valor_nuevo" TEXT,
    "fecha_actualizacion" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "notificaciones" (
    "id" SERIAL,
    "titulo" TEXT NOT NULL,
    "mensaje" TEXT NOT NULL,
    "tipo" TEXT DEFAULT 'info'::text,
    "creador_id" INTEGER,
    "destinatario_id" INTEGER,
    "leida" INTEGER DEFAULT 0,
    "leida_at" TIMESTAMP,
    "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    "prioridad" TEXT DEFAULT 'normal'::text,
    "archivada" INTEGER DEFAULT 0,
    "accion_url" TEXT,
    "accion_texto" TEXT,
    "fecha_expiracion" TIMESTAMP,
    "accion_modulo" TEXT,
    "es_novedad" INTEGER DEFAULT 0,
    "recordatorio_id" INTEGER,
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "permisos_equipo" (
    "id" SERIAL,
    "equipo_id" INTEGER NOT NULL,
    "permiso" VARCHAR(100) NOT NULL,
    "concedido_por" INTEGER,
    "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("id"),
    UNIQUE ("equipo_id", "permiso")
);

CREATE TABLE IF NOT EXISTS "permisos_roles" (
    "id" SERIAL,
    "rol" VARCHAR(20) NOT NULL,
    "permiso" VARCHAR(100) NOT NULL,
    "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("id"),
    UNIQUE ("rol", "permiso")
);

CREATE TABLE IF NOT EXISTS "plantillas" (
    "id" SERIAL,
    "usuario_id" INTEGER NOT NULL,
    "nombre" TEXT NOT NULL,
    "contenido" TEXT NOT NULL,
    "creada_en" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    "actualizada_en" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "recordatorios" (
    "id" SERIAL,
    "solicitud_id" INTEGER NOT NULL,
    "gestion_maestro_id" INTEGER,
    "usuario_id" INTEGER NOT NULL,
    "canal" TEXT DEFAULT 'Llamada'::text NOT NULL,
    "fecha_recordatorio" TIMESTAMP NOT NULL,
    "nota" TEXT,
    "estado" TEXT DEFAULT 'pendiente'::text NOT NULL,
    "notificado" INTEGER DEFAULT 0 NOT NULL,
    "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    "completed_at" TIMESTAMP,
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "relaciones" (
    "id" SERIAL,
    "usuario_id" INTEGER NOT NULL,
    "identificacion" TEXT,
    "cliente" TEXT,
    "celular" TEXT,
    "estado_relacion" TEXT,
    "fecha_inicio_relacion" DATE,
    "fecha_fin_relacion" DATE,
    "fecha_fin_credito" DATE,
    "fecha_fin_fidelizacion" DATE,
    "proxima_baja" DATE,
    "motivo_ruptura" TEXT,
    "numero_operaciones" INTEGER DEFAULT 0,
    "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
