    "ingreso_mensual" NUMERIC(12,2),
    "correo_electronico" TEXT,
    "destacado" INTEGER DEFAULT 0,
    "vendedor" TEXT,
    "campana_id" INTEGER,
    "observaciones" TEXT,
    "no_aplica_credito" INTEGER DEFAULT 1 NOT NULL,
    PRIMARY KEY ("id"),
    UNIQUE ("id_solicitud")
